#include <iostream>
#include <sstream>
#include <string>

bool leer_ficha(const std::string& texto, std::string& codigo, int& cajas) {
    std::istringstream entrada{texto};
    std::string candidato_codigo;
    int candidato_cajas{0};
    if (!(entrada >> candidato_codigo >> candidato_cajas)) return false;
    if (candidato_codigo.size() != 4) return false;
    for (char caracter : candidato_codigo) {
        if (caracter < '0' || caracter > '9') return false;
    }
    if (candidato_cajas < 0 || candidato_cajas > 20) return false;
    char sobrante{};
    if (entrada >> sobrante) return false;
    codigo = candidato_codigo;
    cajas = candidato_cajas;
    return true;
}

void probar(const std::string& texto) {
    std::string codigo{"0999"};
    int cajas{19};
    const bool aceptada{leer_ficha(texto, codigo, cajas)};
    std::cout << aceptada << ':' << codigo << ':' << cajas << '\n';
}

int main() {
    probar("0007 03");
    probar("0123 20");
    probar("0000 0");
    probar("7 3");
    probar("00x7 3");
    probar("0007 tres");
    probar("0007 21");
